import { describe, test, expect } from 'vitest';
import { ZimmInlineMessage } from './zimmInlineMessage.css';

/**
 * Recipe wiring — SFCC-795 §11.2 pass criteria 2 and 6. Reads the exported recipe object
 * directly so these assert the real resolved token references, not a rendered component's
 * computed style (jsdom does not reliably resolve custom-property values) and not a hardcoded
 * hex duplicate of the foundation source.
 */
describe('ZimmInlineMessage — recipe wiring', () => {
  test('error variant resolves to the real status-error colour token var, not a hardcoded hex', () => {
    const error = ZimmInlineMessage.variants!.error as Record<string, unknown>;
    expect(error.color).toBe('var(--zimm-color-status-error)');
    expect(error.color).not.toMatch(/#/);
  });

  test('warning variant resolves to the real muted-text colour token var, not a hardcoded hex', () => {
    const warning = ZimmInlineMessage.variants!.warning as Record<string, unknown>;
    expect(warning.color).toBe('var(--zimm-color-text-muted)');
    expect(warning.color).not.toMatch(/#/);
  });

  test('no low-stock (or any third) variant exists in the recipe', () => {
    expect(Object.keys(ZimmInlineMessage.variants!).sort()).toEqual(['error', 'warning']);
  });

  test('caption textStyle is overridden to regular weight, not left at its medium default', () => {
    const base = ZimmInlineMessage.baseStyle as Record<string, unknown>;
    expect(base.textStyle).toBe('caption');
    expect(base.fontWeight).toBe('var(--zimm-font-weight-regular)');
  });

  test('spans the full row width, matching the Figma "w-full" annotation', () => {
    const base = ZimmInlineMessage.baseStyle as Record<string, unknown>;
    expect(base.width).toBe('full');
  });
});

