276	    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
277	    expect(cartItemCalls).toHaveLength(1);
278	    expect(cartItemCalls[0][1]).toEqual({ hasError: false });
279	  });
280	
281	  test('message with variant="warning": renders the message, but ZimmCartItem still resolves hasError=false', () => {
282	    renderWithProviders(
283	      <ProductItem
284	        product={MOCK_LINE_ITEM}
285	        message={{ variant: 'warning', text: 'Maximum purchase quantity reached for this size' }}
286	      />,
287	    );
288	
289	    expect(screen.getByText('Maximum purchase quantity reached for this size')).toBeInTheDocument();
290	
291	    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
292	    expect(cartItemCalls).toHaveLength(1);
293	    expect(cartItemCalls[0][1]).toEqual({ hasError: false });
294	  });
295	
296	  test('message with variant="error": renders the message, and ZimmCartItem resolves hasError=true', () => {
297	    renderWithProviders(
298	      <ProductItem product={MOCK_LINE_ITEM} message={{ variant: 'error', text: 'This item is unavailable' }} />,
299	    );
300	
301	    expect(screen.getByText('This item is unavailable')).toBeInTheDocument();
302	
303	    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
304	    expect(cartItemCalls).toHaveLength(1);
305	    expect(cartItemCalls[0][1]).toEqual({ hasError: true });
306	  });
307	
308	  // SFCC-795 pass criterion 4: real DOM-order assertion via compareDocumentPosition, not just
309	  // "both nodes are present somewhere."
310	  test('message renders in DOM order between the stepper and the actions (secondaryActions)', () => {
311	    renderWithProviders(
312	      <ProductItem
313	        product={MOCK_LINE_ITEM}
314	        secondaryActions={<button type="button">Edit</button>}
315	        message={{ variant: 'error', text: 'This item is unavailable' }}
316	      />,
317	    );
318	
319	    const stepperNode = screen.getByText('Quantity:');
320	    const messageNode = screen.getByTestId('zimm-inline-message');
321	    const actionsNode = screen.getByRole('button', { name: 'Edit' });
322	
323	    // messageNode follows stepperNode in document order.
324	    expect(stepperNode.compareDocumentPosition(messageNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
325	    // actionsNode follows messageNode in document order — i.e. the message precedes the actions row.
326	    expect(messageNode.compareDocumentPosition(actionsNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
327	  });
328	});
