// same fix shape, as testing.md's documented ZimmIcon workaround, just via a different import
// path (PromoPopover, not ZimmIcon) — not fixable from this test file beyond mocking it away.
vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
}));

vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
  return {
    ...actual,
    usePromotions: () => ({ data: undefined }),
    useProducts: () => ({ data: undefined, isLoading: false }),
    useProduct: () => ({ data: undefined, isLoading: false }),
  };
});

// Bypasses the real utility's own variationAttributes/variationValues matching logic — this
// test is about ProductItem's own render contract (does a combined value render as one node),
// not about re-proving getDisplayVariationValues' own correctness. See
// item-variant/item-attributes.tsx's own SFCC-270 docblock for combineAttributeValues' contract.
vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
  return {
    ...actual,
    getDisplayVariationValues: () => ({ Colour: 'Lilac Sand', Size: 'One size' }),
  };
});

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseMultiStyleConfig = vi.mocked(useMultiStyleConfig);

// ChakraProvider with this project's own theme is required, not optional here — without it,
// `textStyle="productNames"`/`"price"`/`"caption"` resolve against Chakra's default (empty)
// textStyles, and item-price.tsx's `useBreakpointValue` throws outright reading
// `theme.breakpoints` off an undefined theme. Same setup zimmButton's own test uses.
const renderWithProviders = (ui: React.ReactElement) =>
  render(
    <ChakraProvider theme={theme}>
      <MemoryRouter>
        <IntlProvider locale="en-AU" defaultLocale="en-AU">
          {ui}
        </IntlProvider>
      </MemoryRouter>
    </ChakraProvider>,
  );

const MOCK_LINE_ITEM = {
  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
  productId: '25595021M',
  id: '25595021M',
  productName: 'Lilac Sand Silk Midi Dress',
  name: 'Lilac Sand Silk Midi Dress',
  price: 495,
  priceAfterItemDiscount: 495,
  pricePerUnit: 495,
  quantity: 1,
  imageGroups: [
    {
      viewType: 'small',
      images: [{ alt: 'Lilac Sand Silk Midi Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
    },
  ],
};

describe('ProductItem', () => {
  // jsdom has no matchMedia implementation, and item-price.tsx's `isDesktop` uses
  // useBreakpointValue internally, which calls it — a per-file polyfill, not a change to the
  // frozen vitest.setup.ts (Tier 1). Same pattern and reasoning as drawer-menu/index.test.tsx's
  // own beforeEach.
  beforeEach(() => {
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: vi.fn().mockImplementation((query: string) => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    });

    mockUseMultiSite.mockReturnValue({
      site: { id: 'ZimmermannAU' },
      buildUrl: (path: string) => path,
    });

    // SFCC-795: fresh call history per test — mockUseMultiStyleConfig still delegates to the
    // real implementation (see the top-of-file vi.mock), this only clears recorded .mock.calls.
    mockUseMultiStyleConfig.mockClear();
  });

  test('renders the image with an alt, the name uppercase, the price, and one combined colour+size node', () => {
    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

    // Image renders with an alt.
    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();

    // Name renders uppercase (textStyle="productNames" sets text-transform, not literal casing —
    // the DOM text content itself stays as authored). Asserted on the <Heading> textStyle is
    // actually applied to, not the nested <Link> — see item-variant/index.test.tsx's own note
    // on why (text-transform is CSS-inherited, and jsdom's getComputedStyle does not reliably
    // resolve inherited declarations).
    expect(screen.getByRole('heading', { level: 2 })).toHaveStyle({ textTransform: 'uppercase' });

    // Price renders — DisplayPrice/CurrentPrice formats $495.00 via react-intl; rendered twice
    // (mobile + desktop slots both exist in the DOM under jsdom, which does not evaluate CSS
    // media queries — see header/rightBar/index.test.tsx's own note on this exact behaviour).
    expect(screen.getAllByText('$495.00').length).toBeGreaterThan(0);

    // The colour+size string renders as ONE text node containing both values — not two
    // separate nodes. An exact-string query only matches if both values live in the same node.
    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
  });

  // Round 2 rework, must-fix 4: the gift-card capability slot. Only the capability is asserted
  // here — not real gift-card detection, which this build still cannot do (see this component's
  // own docblock).
  test('hideStepperAndActions suppresses the stepper and every actions surface, and nothing throws', () => {
    expect(() =>
      renderWithProviders(
        <ProductItem
          product={MOCK_LINE_ITEM}
          primaryAction={<button type="button">Remove</button>}
          secondaryActions={<button type="button">Edit</button>}
          deliveryActions={<span>Ship to store</span>}
          hideStepperAndActions
        />,
      ),
    ).not.toThrow();

    // Stepper: ProductQuantityPicker's own "Quantity:" label is the only source of this text in
    // this render tree (product-item/index.tsx never passes includeQuantity to
    // CartItemVariantAttributes), so its absence proves the stepper itself did not render.
    expect(screen.queryByText('Quantity:')).not.toBeInTheDocument();

    // Actions: primaryAction/secondaryActions/deliveryActions all suppressed.
    expect(screen.queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Edit' })).not.toBeInTheDocument();
    expect(screen.queryByText('Ship to store')).not.toBeInTheDocument();

    // The rest of the component is unaffected — image/name/price/attributes still render.
    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();
    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
  });

  test('every existing caller (hideStepperAndActions omitted) is unaffected — the stepper and actions still render', () => {
    renderWithProviders(
      <ProductItem
        product={MOCK_LINE_ITEM}
        primaryAction={<button type="button">Remove</button>}
        secondaryActions={<button type="button">Edit</button>}
        deliveryActions={<span>Ship to store</span>}
      />,
    );

    expect(screen.getByText('Quantity:')).toBeInTheDocument();
    expect(screen.getAllByRole('button', { name: 'Remove' }).length).toBeGreaterThan(0);
    expect(screen.getByRole('button', { name: 'Edit' })).toBeInTheDocument();
    expect(screen.getAllByText('Ship to store').length).toBeGreaterThan(0);
  });

  // CodeRabbit (SFCC-11 cumulative review): product-quantity-picker.tsx's handleQuantityChange
  // unconditionally calls `.then(...)` on onItemQuantityChange's return value. The old default,
  // `noop`, returned undefined synchronously - `undefined.then` throws before this test's key
  // handler even finishes. This proves a caller that omits the prop entirely can still actually
  // change the quantity without throwing, not just that rendering alone doesn't throw.
  //
  // Uses an ArrowUp keydown on the quantity input, not a click/mousedown on the increment button:
  // confirmed empirically (not assumed) that fireEvent.click and fireEvent.mouseDown on the
  // button never reach handleQuantityChange at all in this environment - a version of this test
  // written against the pre-fix `noop` default still passed with either, because the interaction
  // itself never fired, not because the fix was safe. ArrowUp on the input reliably invokes the
  // real onChange -> handleQuantityChange chain.
  //
  // Mutation-tested against the actual pre-fix default: the resulting TypeError is thrown
  // asynchronously inside Chakra's own number-input internals (a React event-handler microtask),
  // not synchronously inside this test's own call stack - so `not.toThrow()` itself does not
  // catch it, and the specific `test()` block still reports as passed. What DOES catch it: Vitest
  // reports the async throw as an unhandled error for the run and the process exits non-zero
  // (confirmed directly: exit code 1 with the bug present, exit code 0 with the fix in place) -
  // which is exactly what CI gates on. Noted here so a future reader isn't confused about why an
  // apparently-clean assertion is the real regression guard; the throw itself is the proof.
  test('omitting onItemQuantityChange and actually changing quantity does not throw', () => {
    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

    expect(() => {
      fireEvent.keyDown(screen.getByLabelText('Quantity'), { key: 'ArrowUp' });
    }).not.toThrow();
  });

  // SFCC-795 pass criterion 7: `message` omitted (every existing caller today) renders nothing,
  // and ZimmCartItem resolves `hasError` to false. product-item.css.test.ts proves separately,
  // at the recipe level, that hasError:false keeps the Item Details gap at its existing 12px
  // desktop token — this test proves the WIRING that gets it there (see this file's own
  // docblock for why not a computed-style assertion on the media-query-scoped gap value itself).
  test('message omitted: nothing renders, and ZimmCartItem resolves hasError=false', () => {
    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

    expect(screen.queryByTestId('zimm-inline-message')).not.toBeInTheDocument();

    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
    expect(cartItemCalls).toHaveLength(1);
    expect(cartItemCalls[0][1]).toEqual({ hasError: false });
  });

  test('message with variant="warning": renders the message, but ZimmCartItem still resolves hasError=false', () => {
    renderWithProviders(
      <ProductItem
        product={MOCK_LINE_ITEM}
        message={{ variant: 'warning', text: 'Maximum purchase quantity reached for this size' }}
      />,
    );

    expect(screen.getByText('Maximum purchase quantity reached for this size')).toBeInTheDocument();

    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
    expect(cartItemCalls).toHaveLength(1);
    expect(cartItemCalls[0][1]).toEqual({ hasError: false });
  });

  test('message with variant="error": renders the message, and ZimmCartItem resolves hasError=true', () => {
    renderWithProviders(
      <ProductItem product={MOCK_LINE_ITEM} message={{ variant: 'error', text: 'This item is unavailable' }} />,
    );

    expect(screen.getByText('This item is unavailable')).toBeInTheDocument();

    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
    expect(cartItemCalls).toHaveLength(1);
    expect(cartItemCalls[0][1]).toEqual({ hasError: true });
  });

  // SFCC-795 pass criterion 4: real DOM-order assertion via compareDocumentPosition, not just
  // "both nodes are present somewhere."
  test('message renders in DOM order between the stepper and the actions (secondaryActions)', () => {
    renderWithProviders(
      <ProductItem
        product={MOCK_LINE_ITEM}
        secondaryActions={<button type="button">Edit</button>}
        message={{ variant: 'error', text: 'This item is unavailable' }}
      />,
    );

    const stepperNode = screen.getByText('Quantity:');
    const messageNode = screen.getByTestId('zimm-inline-message');
    const actionsNode = screen.getByRole('button', { name: 'Edit' });

    // messageNode follows stepperNode in document order.
    expect(stepperNode.compareDocumentPosition(messageNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
    // actionsNode follows messageNode in document order — i.e. the message precedes the actions row.
    expect(messageNode.compareDocumentPosition(actionsNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
  });
});

