import { describe, test, expect } from 'vitest';
import { ZimmCartItem } from './product-item.css';
import { breakpoints } from 'app/theme/foundation';

/**
 * Recipe wiring — SFCC-795 §11.2 pass criterion 3. Reads the exported recipe function directly
 * (resolved at both `hasError` states) so these assert the real resolved token references, not a
 * rendered component's computed style (jsdom does not reliably resolve media-query-scoped
 * custom-property values).
 */
const DESKTOP_MEDIA_QUERY = `@media (min-width: ${breakpoints.md})`;

describe('ZimmCartItem — recipe wiring (Item Details gap / hasError)', () => {
  test('details gap is the existing 12px desktop token by default (hasError omitted)', () => {
    const styles = ZimmCartItem.baseStyle({});
    const details = styles.details as Record<string, unknown>;
    const desktop = details[DESKTOP_MEDIA_QUERY] as Record<string, unknown>;
    expect(desktop.gap).toBe('var(--zimm-scale-s)');
    // Mobile step is untouched by hasError — asserted here too so a future change to the
    // default branch can't silently widen the mobile value as a side effect.
    expect(details.gap).toBe('var(--zimm-scale-xl)');
  });

  test('details gap is the existing 12px desktop token when hasError is explicitly false', () => {
    const styles = ZimmCartItem.baseStyle({ hasError: false });
    const desktop = (styles.details as Record<string, unknown>)[DESKTOP_MEDIA_QUERY] as Record<string, unknown>;
    expect(desktop.gap).toBe('var(--zimm-scale-s)');
  });

  test('details gap widens to the 16px token when hasError is true, mobile gap unaffected', () => {
    const styles = ZimmCartItem.baseStyle({ hasError: true });
    const details = styles.details as Record<string, unknown>;
    const desktop = details[DESKTOP_MEDIA_QUERY] as Record<string, unknown>;
    expect(desktop.gap).toBe('var(--zimm-scale-m)');
    expect(details.gap).toBe('var(--zimm-scale-xl)');
  });

  test('row and info parts are unaffected by hasError', () => {
    const withError = ZimmCartItem.baseStyle({ hasError: true });
    const withoutError = ZimmCartItem.baseStyle({ hasError: false });
    expect(withError.row).toEqual(withoutError.row);
    expect(withError.info).toEqual(withoutError.info);
  });
});

