--- zimmNavItem/zimmNavItem.css.ts ---
import { defineStyleConfig, type SystemStyleObject } from '@chakra-ui/react';

// Figma's footer-item cap-height boxes (8px/22px for one/two lines) don't map 1:1 to a browser
// line box; 4.5px each side reproduces the same 24px/38px totals. No matching spacing.ts entry
// — provisional pending UI-designer sign-off.
const NAV_ITEM_PAD_Y = '4.5px';

const baseStyle = {
  // fontFamily deliberately overrides textStyle: Figma's Default/Navigation binds body font,
  // not the heading family textStyles.navigation carries.
  textStyle: 'navigation',
  fontFamily: 'var(--zimm-font-family-body)',
  display: 'inline-flex',
  // A floor, not a fixed height — minHeight lets multi-line labels (e.g. "ACKNOWLEDGEMENT OF
  // COUNTRY") grow past it without a caller needing to override.
  minHeight: 'var(--zimm-scale-xl)', // 1.5rem (24px) — Figma: h-[24px]
  lineHeight: 'var(--zimm-font-lineheight-4xs)', // 0.875rem (14px)
  paddingBlock: NAV_ITEM_PAD_Y,
  justifyContent: 'center',
  alignItems: 'center',
  whiteSpace: 'normal',
  cursor: 'pointer',
  background: 'none',
  border: 'none',
  // paddingInline, not the `padding` shorthand — a shorthand would reset paddingBlock above.
  paddingInline: 0,
  textDecoration: 'none',
  // transparent (not 'none') so border-color transitions smoothly without a display change.
  '& > span': {
    borderBottom: 'var(--zimm-border-width-default) solid transparent',
    transition: `border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)`,
  },
  _hover: {
    '& > span': { borderBottomColor: 'currentColor' },
  },
  // Permanent underline regardless of hover — either the genuine current page
  // (aria-current="page") or a visually-active-only state with no accessible-current
  // implication (data-visually-active, see ZimmNavItemProps.visuallyActive's doc comment).
  '&[aria-current="page"] > span, &[data-visually-active="true"] > span': {
    borderBottomColor: 'currentColor',
  },
};

const variants = {
  light: {
    color: 'var(--zimm-color-text-default)',
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  inverse: {
    color: 'var(--zimm-color-text-inverse)',
    _focusVisible: {
      outline: 'var(--zimm-border-width-default) solid var(--zimm-color-text-inverse)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  // Desktop "Find your size" — sentence-case, hover/grow underline via growUnderline prop.
  // textTransform: 'none' overrides the 'uppercase' that textStyle="navigation" sets in baseStyle.
  sizeGuide: {
    color: 'var(--zimm-color-text-default)',
    textTransform: 'none',
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  // Mobile "Find your size" — permanently underlined (no hover on mobile) + sentence-case.
  // Do NOT combine with growUnderline: that swaps the border for a ::after that only scales
  // up on :hover, leaving no underline on mobile. ZimmSizeSelector picks by breakpoint.
  sizeGuideLink: {
    color: 'var(--zimm-color-text-default)',
    textTransform: 'none',
    '& > span': { borderBottomColor: 'currentColor' },
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
};

export const ZimmNavItem = defineStyleConfig({
  baseStyle,
  variants,
  defaultProps: { variant: 'light' },
});

// Grow/reverse underline — opt-in via ZimmNavItem's `growUnderline` prop, used only at
// navigation call sites (top nav bar, mega-menu leaf links). Footer keeps the fade above
// unchanged. A CSS border can't itself be "grown" via transform, so this replaces the inner
// span's border-bottom with a `::after` pseudo-element (position:relative on the span makes it
// the ::after's containing block) and scales that instead. Duration/easing are provisional
// pending final design confirmation.
export const GROW_UNDERLINE_SX: SystemStyleObject = {
  '& > span': {
    position: 'relative',
    borderBottom: 'none',
  },
  '& > span::after': {
    content: '""',
    position: 'absolute',
    left: 0,
    right: 0,
    bottom: 0,
    height: 'var(--zimm-border-width-default)',
    background: 'currentColor',
    transform: 'scaleX(0)',
    // Fixed at 'left' in both states, never flips to 'right' — a viewer perceives an
    // animation's direction by which edge *moves*, not which edge is anchored, so flipping the
    // origin on blur (an earlier version of this rule) made the retreat look left-to-right
    // instead of the intended right-to-left reversal of the grow.
    transformOrigin: 'left center',
    transition: 'transform var(--zimm-motion-duration-fast) ease-in',
  },
  '&:hover > span::after, &[aria-current="page"] > span::after, &[data-visually-active="true"] > span::after': {
    transform: 'scaleX(1)',
  },
};
--- zimmWishlistBadge/zimmWishlistBadge.css.ts ---
import type { SystemStyleObject } from '@chakra-ui/react';

// Icon-only disabled opacity — same value zimmButton.css.ts's `icon`/`iconInverse` variants use,
// defined locally rather than imported: this recipe is deliberately isolated from
// zimmButton.css.ts (see index.tsx's own comment) so nothing here depends on that file.
const OPACITY_DISABLED = 0.4;

/**
 * Recipe for the PDP wishlist toggle badge (Figma node 40000214:6159, "AtomAddToWishlist").
 * Single-part — the whole control is one styled element, same shape as zimmProductName.css.ts.
 *
 * Figma-confirmed (via get_variable_defs on node 40000214:6159 / 40003021:101731): 4px padding
 * (alias/space/100 → var(--zimm-scale-2xs)), #191919 icon colour (alias/color/icon/default →
 * var(--zimm-color-icon-default)). The explicit 24px width/height reuses the same
 * var(--zimm-scale-xl) token zimmContactIconRow.css.ts's `iconLink` part already uses for an
 * identical icon-only 24px touch target (WCAG 2.2 SC 2.5.8) — not imported from there, just the
 * same foundation token applied the same way.
 *
 * No hover/pressed/loading state exists in Figma for this control (confirmed via
 * get_design_context — only Default/Selected icon swap). The _disabled/_focusVisible states
 * below are inherited conventions from elsewhere in this app, not confirmed Figma values —
 * flagged here so a future design review knows to check them specifically.
 */
export const ZimmWishlistBadge = {
  baseStyle: {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: 'var(--zimm-scale-xl)', // 24px
    height: 'var(--zimm-scale-xl)', // 24px
    padding: 'var(--zimm-scale-2xs)', // 4px — alias/space/100
    background: 'transparent',
    border: 'none',
    cursor: 'pointer',
    color: 'var(--zimm-color-icon-default)',
    _disabled: {
      opacity: OPACITY_DISABLED,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  } satisfies SystemStyleObject,
};

